import hashlib
import json
import os
import plistlib
from pathlib import Path
from PIL import Image, ImageDraw, ImageFont

root = Path(__file__).resolve().parent / 'shaders'
mac2jb = plistlib.loads((Path(__file__).resolve().parents[3] / 'gui/Info.plist').read_bytes())
version = mac2jb['CFBundleShortVersionString']
atlas = Image.new('L', (1024, 2048))
draw = ImageDraw.Draw(atlas)
font = os.environ.get('MAC2JB_HBLAUNCHER_FONT') or str(Path(__file__).resolve().parents[3] / 'homebrew/fonts/DejaVuSans.ttf')
labels = [
    ('TITLE', 'MintBrew', 82),
    ('SUBTITLE', 'by cpypwn', 25),
    ('NOTITLES', 'No titles found', 34),
    ('EMPTYHINT', 'Your library is empty.', 20),
    ('SELECT', 'Select', 19),
    ('BACK', 'Back', 19),
    ('EMPTY', 'App unavailable', 34),
    ('DETAIL', 'Refresh the app list and try again.', 19),
    ('CLOSE', 'Press B to return', 18),
    ('BUTTON_A', 'A', 16),
    ('BUTTON_B', 'B', 16),
    ('VERSION', f'mac2jb v{version}', 16),

]
labels += [(f'DIGIT{i}', str(i), 34) for i in range(10)]
header = ['// generated by homebrew-launcher/launcher-text.py']
y = 2
for name, text, size in labels:
    face = ImageFont.truetype(font, size)
    box = draw.textbbox((0, 0), text, font=face)
    width, height = box[2] - box[0], box[3] - box[1]
    assert width + 4 <= 1024 and y + height + 2 <= 2048
    draw.text((2 - box[0], y - box[1]), text, fill=255, font=face)
    header.append(f'const ivec4 TEXT_{name} = ivec4(2, {y}, {width}, {height});')
    y += height + 8
header.append('const ivec4 DIGITS[10] = ivec4[10](' + ','.join(f'TEXT_DIGIT{i}' for i in range(10)) + ');')
bitmap = atlas.tobytes()
layout = '\n'.join(header) + '\n'
(root / 'launcher-text.bin').write_bytes(bitmap)
(root / 'launcher-text.glsl').write_text(layout)
(root / 'launcher-text.json').write_text(json.dumps({
    'mac2jbVersion': version,
    'atlasSha256': hashlib.sha256(bitmap).hexdigest(),
    'layoutSha256': hashlib.sha256(layout.encode()).hexdigest(),
}, sort_keys=True) + '\n')
atlas.save(root / 'launcher-text.png')
print(f'Type atlas: 1024 x 2048, {y} rows used')
